from collections import deque
from typing import List

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_nums = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)
        for i in range(n):
            prefix_nums[i+1] = prefix_nums[i] + nums[i]
            prefix_cost[i+1] = prefix_cost[i] + cost[i]

        INF = 10**18
        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for j in range(1, n + 1):
            dq = deque()
            l_start = j - 1
            if l_start >= 0 and dp[l_start][j-1] != INF:
                m = -prefix_cost[l_start]
                c = dp[l_start][j-1]
                dq.append((m, c))

            for i in range(j, n + 1):
                A = prefix_nums[i] + k * j
                B = prefix_cost[i]

                while len(dq) >= 2:
                    m1, c1 = dq[0]
                    m2, c2 = dq[1]
                    if m1 * A + c1 >= m2 * A + c2:
                        dq.popleft()
                    else:
                        break

                if dq:
                    m, c = dq[0]
                    min_val = m * A + c
                    dp[i][j] = min_val + A * B
                else:
                    dp[i][j] = INF

                if dp[i][j-1] != INF:
                    m_new = -prefix_cost[i]
                    c_new = dp[i][j-1]
                    while len(dq) >= 2:
                        m1, c1 = dq[-2]
                        m2, c2 = dq[-1]
                        m3, c3 = m_new, c_new
                        if (c3 - c1) * (m1 - m2) <= (c2 - c1) * (m1 - m3):
                            dq.pop()
                        else:
                            break
                    dq.append((m_new, c_new))

        return min(dp[n][1:])

import sys

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        num_test_cases = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(num_test_cases):
        try:
            R = int(next(iterator))
            B = int(next(iterator))
        except StopIteration:
            break

        # Condition 1: R must be even.
        # Reasoning: Red pieces flip the parity of (r+c), Blue pieces preserve it.
        # For a cycle to exist, the total number of parity flips (Red pieces) must be even.
        if R % 2 != 0:
            results.append("No")
        # Condition 2: If R=0, we have a cycle of only Blue pieces.
        # Blue moves connect (r,c) to (r±1, c±1). This graph is bipartite based on row parity (r % 2).
        # Any cycle in a bipartite graph must have even length.
        # So if R=0 and B is odd, it's impossible.
        elif R == 0 and B % 2 != 0:
            results.append("No")
        else:
            results.append("Yes")
            # Construct the solution
            # Strategy:
            # 1. Place all R red pieces alternating between (1,1) and (1,2).
            #    Since R is even, the sequence ends at (1,2) and starts at (1,1).
            # 2. Place all B blue pieces alternating between (2,2) and (1,1).
            #    We choose the starting point based on B's parity to ensure connectivity.

            output_lines = []

            # Add Red pieces
            for i in range(1, R + 1):
                if i % 2 == 1:
                    output_lines.append("R 1 1")
                else:
                    output_lines.append("R 1 2")

            # Add Blue pieces
            if B > 0:
                if B % 2 == 1:
                    # If B is odd, start at (2,2) so that the last one is also (2,2).
                    # (2,2) is adjacent to (1,2) [last Red] and (1,1) [first Red].
                    for i in range(1, B + 1):
                        if i % 2 == 1:
                            output_lines.append("B 2 2")
                        else:
                            output_lines.append("B 1 1")
                else:
                    # If B is even, start at (1,1) so that the last one is (2,2).
                    # (1,1) is adjacent to (1,2) [last Red].
                    # (2,2) is adjacent to (1,1) [first Red].
                    for i in range(1, B + 1):
                        if i % 2 == 1:
                            output_lines.append("B 1 1")
                        else:
                            output_lines.append("B 2 2")

            results.append("\n".join(output_lines))

    print("\n".join(results))

if __name__ == '__main__':
    solve()

