class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        inf = n + 1
        events = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            events[a].append(b)

        min1_val = inf
        count1 = 0
        min2_val = inf
        best_constraint = None
        F_S = 0
        constraint_increase = {}

        for i in range(n, 0, -1):
            for b in events[i]:
                if b < min1_val:
                    min2_val = min1_val
                    min1_val = b
                    count1 = 1
                    best_constraint = (i, b)
                elif b == min1_val:
                    count1 += 1
                    best_constraint = None
                elif b < min2_val:
                    min2_val = b

            R_i = min1_val
            if R_i == inf:
                count_valid = n - i + 1
            else:
                count_valid = R_i - i

            F_S += count_valid

            if count1 == 1 and R_i != inf:
                p = best_constraint
                inc = min2_val - R_i if min2_val != inf else (n - R_i + 1)
                constraint_increase[p] = constraint_increase.get(p, 0) + inc

        max_increase = 0
        if constraint_increase:
            max_increase = max(constraint_increase.values())

        return F_S + max_increase

