class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Sort points by x-coordinate, then by y-coordinate
        points_sorted = sorted(points, key=lambda p: (p[0], p[1]))
        n = len(points_sorted)

        # Helper function to compute Manhattan distance
        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        # DFS with backtracking to check if we can select k points with pairwise distances >= d
        def can_select(d: int) -> bool:
            # We'll use a list to keep track of currently selected points for backtracking
            picked = []

            def dfs(idx: int, count: int) -> bool:
                # If we have selected k points, return True
                if count == k:
                    return True
                # If we've gone through all points, return False
                if idx == n:
                    return False
                # Pruning: if remaining points are not enough to reach k
                if n - idx < k - count:
                    return False

                # Option 1: Skip the current point
                if dfs(idx + 1, count):
                    return True

                # Option 2: Try to include the current point if it's compatible with all selected points
                current = points_sorted[idx]
                compatible = True
                for p in picked:
                    if manhattan(current, p) < d:
                        compatible = False
                        break

                if compatible:
                    picked.append(current)
                    if dfs(idx + 1, count + 1):
                        return True
                    picked.pop()  # Backtrack

                return False

            return dfs(0, 0)

        # Binary search for the maximum minimum distance
        low = 1
        high = 2 * side
        ans = 1

        while low <= high:
            mid = (low + high) // 2
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        star_indices = [i for i, char in enumerate(p) if char == '*']
        if len(star_indices) != 2:
            return -1

        idx1, idx2 = star_indices
        part1 = p[:idx1]
        part2 = p[idx1+1:idx2]
        part3 = p[idx2+1:]

        # Precompute L: L[j] = largest i such that s[i:i+len(part1)] == part1 and i + len(part1) <= j
        L = [-1] * (n + 1)
        if part1 == "":
            for j in range(n + 1):
                L[j] = j
        else:
            len1 = len(part1)
            end_occurrence = [-1] * n
            for i in range(n - len1 + 1):
                if s[i:i+len1] == part1:
                    end_index = i + len1 - 1
                    if end_index < n:
                        if i > end_occurrence[end_index]:
                            end_occurrence[end_index] = i

            current_max = -1
            for j in range(n + 1):
                if j > 0:
                    if j-1 < n:
                        if end_occurrence[j-1] > current_max:
                            current_max = end_occurrence[j-1]
                L[j] = current_max

        # Precompute R: R[j] = smallest k such that s[k:k+len(part3)] == part3 and k >= j
        R = [float('inf')] * (n + 1)
        if part3 == "":
            for j in range(n + 1):
                R[j] = j
        else:
            len3 = len(part3)
            current_min = float('inf')
            for j in range(n, -1, -1):
                if j + len3 <= n:
                    if s[j:j+len3] == part3:
                        if j < current_min:
                            current_min = j
                R[j] = current_min

        min_len = float('inf')
        len2 = len(part2)

        if part2 == "":
            for j in range(n + 1):
                if L[j] != -1 and R[j] != float('inf'):
                    length = (R[j] + len3) - L[j]
                    if length < min_len:
                        min_len = length
        else:
            for j in range(n - len2 + 1):
                if s[j:j+len2] == part2:
                    if L[j] != -1 and R[j + len2] != float('inf'):
                        length = (R[j + len2] + len3) - L[j]
                        if length < min_len:
                            min_len = length

        return min_len if min_len != float('inf') else -1

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # suf[i] = minimum cost to make caption[i:n] a good caption
        suf = [float('inf')] * (n + 1)
        suf[n] = 0

        # Compute suf from n-1 down to 0
        for i in range(n - 1, -1, -1):
            # Try all possible block lengths L from 3 to n-i
            for L in range(3, n - i + 1):
                segment = caption[i:i+L]
                # Count frequencies using a fixed array
                freq = [0] * 26
                for char in segment:
                    freq[ord(char) - ord('a')] += 1

                max_freq = 0
                for count in freq:
                    if count > max_freq:
                        max_freq = count

                # Find the smallest char with max_freq
                best_char_for_segment = None
                for idx in range(26):
                    if freq[idx] == max_freq:
                        best_char_for_segment = chr(ord('a') + idx)
                        break

                cost_block = L - max_freq
                if suf[i+L] + cost_block < suf[i]:
                    suf[i] = suf[i+L] + cost_block
                # If equal, we don't update because during reconstruction we will choose the smallest char.

        if suf[0] == float('inf'):
            return ""

        # Reconstruct the lexicographically smallest string
        i = 0
        result = []
        while i < n:
            min_total = float('inf')
            best_L = -1
            best_c = None

            # Try all possible block lengths L from 3 to n-i
            for L in range(3, n - i + 1):
                segment = caption[i:i+L]
                freq = [0] * 26
                for char in segment:
                    freq[ord(char) - ord('a')] += 1

                max_freq = 0
                for count in freq:
                    if count > max_freq:
                        max_freq = count

                best_char_for_segment = None
                for idx in range(26):
                    if freq[idx] == max_freq:
                        best_char_for_segment = chr(ord('a') + idx)
                        break

                cost_block = L - max_freq
                total = cost_block + suf[i+L]

                if total < min_total:
                    min_total = total
                    best_L = L
                    best_c = best_char_for_segment
                elif total == min_total:
                    if best_c is None or best_char_for_segment < best_c:
                        best_c = best_char_for_segment
                        best_L = L

            if best_c is None:
                return ""

            result.append(best_c * best_L)
            i += best_L

        return "".join(result)

