import bisect

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        if n == 0:
            return []

        # Create a list of (end_time, start_time, weight, original_index)
        # We'll sort by end_time, then by start_time, then by original_index for consistency
        sorted_by_end = []
        for idx, interval in enumerate(intervals):
            sorted_by_end.append((interval[1], interval[0], interval[2], idx))
        sorted_by_end.sort(key=lambda x: (x[0], x[1], x[2]))

        # Extract end_times for binary search
        end_times = [x[0] for x in sorted_by_end]

        # best_k_solution[k][j] = (total_weight, list_of_indices) for the best solution of size k that ends at or before sorted_by_end[j].end_time
        best_k_solution = [[None] * n for _ in range(5)]  # k from 1 to 4

        # For k=1:
        current_best = None
        for j in range(n):
            end_time, start_time, weight, idx = sorted_by_end[j]
            if current_best is None or weight > current_best[1] or (weight == current_best[1] and idx < current_best[0]):
                current_best = (idx, weight)
            best_k_solution[1][j] = current_best

        # For k=2,3,4:
        for k in range(2, 5):
            for j in range(n):
                end_time_j, start_time_j, weight_j, idx_j = sorted_by_end[j]
                # Find the best solution of size k-1 that ends before start_time_j
                idx = bisect.bisect_left(end_times, start_time_j)
                if idx > 0:
                    best_prev = best_k_solution[k-1][idx-1]
                    if best_prev is not None:
                        new_solution = best_prev[1] + [idx_j]
                        total_weight = best_prev[0] + weight_j
                        if j == 0:
                            best_k_solution[k][j] = (total_weight, new_solution)
                        else:
                            current_best = best_k_solution[k][j-1]
                            if current_best is None:
                                best_k_solution[k][j] = (total_weight, new_solution)
                            else:
                                if total_weight > current_best[0]:
                                    best_k_solution[k][j] = (total_weight, new_solution)
                                elif total_weight == current_best[0]:
                                    if new_solution < current_best[1]:
                                        best_k_solution[k][j] = (total_weight, new_solution)
                                    else:
                                        best_k_solution[k][j] = current_best
                else:
                    best_k_solution[k][j] = best_k_solution[k][j-1] if j > 0 else None

        # The overall best solution for each k is best_k_solution[k][n-1]
        best_solutions = [None] * 5
        for k in range(1, 5):
            if best_k_solution[k][n-1] is not None:
                best_solutions[k] = best_k_solution[k][n-1]

        # Find the best solution among k=1,2,3,4
        best_overall = None
        for k in range(1, 5):
            if best_solutions[k] is not None:
                weight, indices = best_solutions[k]
                if best_overall is None:
                    best_overall = (weight, indices)
                else:
                    if weight > best_overall[0]:
                        best_overall = (weight, indices)
                    elif weight == best_overall[0]:
                        if indices < best_overall[1]:
                            best_overall = (weight, indices)

        return best_overall[1] if best_overall else []

