class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        # Compute run lengths
        runs = []
        current_run = 1
        for i in range(1, n):
            if s[i] == s[i-1]:
                current_run += 1
            else:
                runs.append(current_run)
                current_run = 1
        runs.append(current_run)

        # Binary search for the minimum maximum run length
        left, right = 1, n
        ans = n

        while left <= right:
            mid = (left + right) // 2
            needed_ops = 0
            for length in runs:
                # Flips needed for a run of 'length' to have max segment 'mid'
                # We need ceil(length / mid) - 1 flips
                segments = (length + mid - 1) // mid
                needed_ops += segments - 1

            if needed_ops <= numOps:
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans

import sys

# Increase recursion depth just in case, though iterative DFS is used
sys.setrecursionlimit(300000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        X = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        B = []
        for _ in range(N):
            B.append(int(next(iterator)))

        P = []
        for _ in range(N):
            P.append(int(next(iterator)) - 1) # Convert to 0-based index

        Q = []
        for _ in range(N):
            Q.append(int(next(iterator)) - 1) # Convert to 0-based index

    except StopIteration:
        return

    # has_red and has_blue arrays to track if a box has red/blue balls
    # Initially based on input A and B
    has_red = [False] * N
    has_blue = [False] * N

    for i in range(N):
        if A[i] > 0:
            has_red[i] = True
        if B[i] > 0:
            has_blue[i] = True

    # BFS to propagate the "has balls" property
    # If a box has red balls, operating on it sends red balls to P[u].
    # So P[u] will have red balls (if P[u] != X).
    # Same for blue balls and Q[u].
    queue = []
    for i in range(N):
        if has_red[i] or has_blue[i]:
            queue.append(i)

    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1

        # Propagate red balls
        if has_red[u]:
            v = P[u]
            if v != X and not has_red[v]:
                has_red[v] = True
                queue.append(v)

        # Propagate blue balls
        if has_blue[u]:
            v = Q[u]
            if v != X and not has_blue[v]:
                has_blue[v] = True
                queue.append(v)

    # Identify the set R of boxes that must be operated on
    R = set()
    for i in range(N):
        if has_red[i] or has_blue[i]:
            R.add(i)

    # We do not need to operate on box X, so remove it from R
    if X in R:
        R.remove(X)

    # If no boxes need to be operated on, 0 operations
    if not R:
        print(0)
        return

    # Build the dependency graph for cycle detection
    # Nodes are in R
    # Edges: u -> P[u] if u has red balls and P[u] in R
    #        u -> Q[u] if u has blue balls and Q[u] in R
    adj = {}
    for u in R:
        adj[u] = []

    for u in R:
        # Red edge
        if has_red[u]:
            v = P[u]
            if v in R:
                adj[u].append(v)
        # Blue edge
        if has_blue[u]:
            v = Q[u]
            if v in R:
                adj[u].append(v)

    # Cycle detection using iterative DFS
    # state: 0 = unvisited, 1 = visiting, 2 = visited
    state = {u: 0 for u in R}
    has_cycle = False

    for start_node in R:
        if state[start_node] != 0:
            continue

        stack = [(start_node, iter(adj[start_node]))]
        state[start_node] = 1

        while stack:
            u, children = stack[-1]

            try:
                v = next(children)
                if state[v] == 1:
                    has_cycle = True
                    break
                if state[v] == 0:
                    state[v] = 1
                    stack.append((v, iter(adj[v])))
                # If state[v] == 2, it's already processed, ignore
            except StopIteration:
                state[u] = 2
                stack.pop()

            if has_cycle:
                break

    if has_cycle:
        print(-1)
    else:
        print(len(R))

