class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY
                return True
            return False

        valid_nums = set()
        for i, num in enumerate(nums):
            if num <= threshold:
                valid_nums.add(num)

        # Map value to index for quick lookup
        val_to_idx = {}
        for i, num in enumerate(nums):
            if num <= threshold:
                val_to_idx[num] = i

        # Iterate over each valid number and connect with its multiples
        for x in valid_nums:
            idx_x = val_to_idx[x]
            multiple = x
            while multiple <= threshold:
                if multiple in val_to_idx:
                    idx_m = val_to_idx[multiple]
                    union(idx_x, idx_m)
                multiple += x

        # Count connected components
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
